window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":165,"source":"خطبه 165.docx","mode":"explicit-parts","parts":["خطبه ۱۶۵\nبخش اول\nمتن:\nو من خطبة له (علیه السلام) يذكر فيها عجيب خلقة الطاوس:\nخلقة الطُيور:\nابْتَدَعَهُمْ خَلْقاً عَجِيباً مِنْ حَيَوَانٍ وَ مَوَاتٍ وَ سَاكِنٍ وَ ذِي حَرَكَاتٍ، وَ أَقَامَ مِنْ شَوَاهِدِ الْبَيِّنَاتِ عَلَى لَطِيفِ صَنْعَتِهِ وَ عَظِيمِ قُدْرَتِهِ، مَا انْقَادَتْ لَهُ الْعُقُولُ مُعْتَرِفَةً بِهِ وَ مَسَلِّمَةً لَهُ، وَ نَعَقَتْ فِي أَسْمَاعِنَا دَلَائِلُهُ عَلَى وَحْدَانِيَّتِهِ، وَ مَا ذَرَأَ مِنْ مُخْتَلِفِ صُوَرِ الْأَطْيَارِ الَّتِي أَسْكَنَهَا أَخَادِيدَ الْأَرْضِ وَ خُرُوقَ فِجَاجِهَا وَ رَوَاسِيَ أَعْلَامِهَا مِنْ ذَاتِ أَجْنِحَةٍ مُخْتَلِفَةٍ وَ هَيْئَاتٍ مُتَبَايِنَةٍ مُصَرَّفَةٍ فِي زِمَامِ التَّسْخِيرِ وَ مُرَفْرِفَةٍ بِأَجْنِحَتِهَا فِي مَخَارِقِ الْجَوِّ الْمُنْفَسِحِ وَ الْفَضَاءِ الْمُنْفَرِجِ، كَوَّنَهَا بَعْدَ إِذْ لَمْ تَكُنْ فِي عَجَائِبِ صُوَرٍ ظَاهِرَةٍ وَ رَكَّبَهَا فِي حِقَاقِ مَفَاصِلَ مُحْتَجِبَةٍ وَ مَنَعَ بَعْضَهَا بِعَبَالَةِ خَلْقِهِ أَنْ يَسْمُوَ فِي الْهَوَاءِ خُفُوفاً وَ جَعَلَهُ يَدِفُّ دَفِيفاً، وَ نَسَقَهَا عَلَى اخْتِلَافِهَا فِي الْأَصَابِيغِ بِلَطِيفِ قُدْرَتِهِ وَ دَقِيقِ صَنْعَتِهِ، فَمِنْهَا مَغْمُوسٌ فِي قَالَبِ لَوْنٍ لَا يَشُوبُهُ غَيْرُ لَوْنِ مَا غُمِسَ فِيهِ، وَ مِنْهَا مَغْمُوسٌ فِي لَوْنِ صِبْغٍ قَدْ طُوِّقَ بِخِلَافِ مَا صُبِغَ بِهِ.\nالطاوس:\nوَ مِنْ أَعْجَبِهَا خَلْقاً الطَّاوُسُ الَّذِي أَقَامَهُ فِي [أَحْسَنِ] أَحْكَمِ تَعْدِيلٍ وَ نَضَّدَ أَلْوَانَهُ فِي أَحْسَنِ تَنْضِيدٍ بِجَنَاحٍ أَشْرَجَ قَصَبَهُ وَ ذَنَبٍ أَطَالَ مَسْحَبَهُ، إِذَا دَرَجَ إِلَى الْأُنْثَى نَشَرَهُ مِنْ طَيِّهِ وَ سَمَا بِهِ مُطِلًّا عَلَى رَأْسِهِ، كَأَنَّهُ قِلْعُ دَارِيٍّ عَنَجَهُ نُوتِيُّهُ، يَخْتَالُ بِأَلْوَانِهِ وَ يَمِيسُ بِزَيَفَانِهِ، يُفْضِي كَإِفْضَاءِ الدِّيَكَةِ وَ يَؤُرُّ بِمَلَاقِحِهِ أَرَّ الْفُحُولِ الْمُغْتَلِمَةِ لِلضِّرَابِ؛ أُحِيلُكَ مِنْ ذَلِكَ عَلَى مُعَايَنَةٍ لَا كَمَنْ يُحِيلُ عَلَى ضَعِيفٍ إِسْنَادُهُ؛ وَ لَوْ كَانَ كَزَعْمِ مَنْ يَزْعُمُ أَنَّهُ يُلْقِحُ بِدَمْعَةٍ تَسْفَحُهَا مَدَامِعُهُ فَتَقِفُ فِي ضَفَّتَيْ جُفُونِهِ وَ أَنَّ أُنْثَاهُ تَطْعَمُ ذَلِكَ ثُمَّ تَبِيضُ لَا مِنْ لِقَاحِ فَحْلٍ سِوَى الدَّمْعِ الْمُنْبَجِسِ، لَمَا كَانَ ذَلِكَ بِأَعْجَبَ مِنْ مُطَاعَمَةِ الْغُرَابِ.\nترجمه:\nخداوند، آفريدگانى شگفت انگيز از حيوان و جماد، ساکن و متحرک، ابداع کرد و نمونه هايى از شواهد آشکار بر صنعت دقيق و قدرت عظيمش را اقامه کرد; آن گونه که عقل ها مطيع و معترف و تسليم او شدند و دلايل يگانگى او در گوش هاى ما طنين انداز شد و اشکال گوناگونى از پرندگان را آفريد; پرندگانى که آن ها را در شکاف هاى زمين و بريدگى درّه ها و قلّه کوه ها مسکن داد; پرندگانى که داراى بال هاى مختلف و شکل هاى گوناگون اند; آن ها که زمامشان در دست پروردگار است و در مسيرى که تعيين فرموده در حرکتند و به وسيله بال هاى خويش در فراخناى هواى گسترده و در فضاى پهناور به پرواز در مى آيند.\nخدا آن ها را با اشکال شگفت آورى از نظر صورت ظاهر پديد آورد و پيکرشان را با استخوان هاى به هم پيوسته که پوشيده (از گوشت) شده ترکيب نمود; بعضى را به سبب سنگينى جسمشان از اين که به آسانى در هوا پرواز کنند بازداشت و چنان قرارداد که بتوانند (در نزديکى زمين) بال و پر بزنند (ولى به سَبُک وَزنان اجازه داد در اوج آسمان به پرواز درآيند) با قدرت دقيق و آفرينش لطيف خويش، پرندگان را به رنگ هاى گوناگونى رنگ آميزى کرد. بعضى تنها يک رنگ دارند بى آن که رنگ ديگرى با آن مخلوط باشد و بعضى آن ها تمام بدنشان يک رنگ دارد; جز طوقى که رنگ ديگر بر دور گردنشان است.\nيکى از عجيب ترين آن ها (پرندگان) از نظر آفرينش، طاووس است که خداوند آن را در موزون ترين شکل آفريد و با رنگ هاى مختلف به بهترين صورت رنگ آميزى نمود; با بال و پرهايى که شهپرهاى آن بر روى يکديگر قرار گرفته و به هم آميخته و دُمى که دامنه آن را گسترده و بر زمين مى کشد. هنگامى که طاووس به سوى جفت خود حرکت مى کند، دم خود را مى گشايد و همچون چترى (بسيار زيبا) بر سر خود سايبان مى سازد; گويى بادبان کشتى است که از سرزمين «دارين» مشک با خود آورده و ناخدا آن را برافراشته است. (در اين حال) او با اين همه رنگ هاى زيبا غرق در غرور مى شود و با حرکات متکبرانه به خود مى نازد; همچون خروس با جفت خود مى آميزد و همانند حيوانات نر که از طغيان شهوت به هيجان آمده اند با او درآميخته باردارش مى کند.\nبراى اثبات آن به مشاهده حسّى حواله مى کنم; نه همچون کسى که به دليل ضعيف ذهنى حواله مى کند و آن گونه که بعضى پنداشته اند، طاووس به وسيله اشکى که از چشم خود فرو مى ريزد جنس ماده را باردار مى کند به اين صورت که قطره اشک در دو طرف پلک هاى جنس نر حلقه مى زند و ماده او آن را مى نوشد سپس تخم مى گذارد، بى آن که با نر آميزش کرده باشد، جز همان قطره اشکى که از چشمش بيرون پريده است، (اين افسانه بى اساسى است و) عجيب تر از افسانه توليد مثل کلاغ نيست.\nتفسیر:\nخلقت عجیب طاووس\nیکی از موضوعاتی که در نهج‌البلاغه قابل‌توجه است، بحث حیوانات است؛ گاهی فقط اشاره‌ای گذرا به حیوان و گاهی به ویژگی‌های خاص آن‌ها پرداخته می‌شود و در چند سطر، به طور تفصیلی درباره آن‌ها سخن به میان می‌آید. در جهان‌بینی توحیدی امیرالمؤمنین (ع)، اشاره به هر کدام از این موجودات، گواهی بر عظمت، قدرت و وجود خداوند متعال است. این خطبه راجع به طاووس و مورچه است.\n♦️ابْتَدَعَهُمْ خَلْقاً عَجِیباً مِنْ حَیوَانٍ وَمَوَاتٍ، وَسَاکنٍ وَذِی حَرَکاتٍ♦️\nخداوند متعال موجودات را آفرید که البته هر کدام از آن‌ها پدیده‌ای شگفت‌انگیز است و آفرینش هر یک، بی‌سابقه و نوپدید بوده و هیچ‌گونه کاستی یا آزمون و خطایی در آن راه نیافته است. خداوند موجودات را از ابتدا کامل و بی‌نقص آفرید؛ برخی مخلوقات جاندار و متحرک [حَیوَان] و برخی دیگر بی‌جان و جماد [مَوَات] هستند. حیوان شامل حیوانات، انسان و گیاهان می‌شود و موات، موجودات غیر ذی‌روح مانند سنگ و چوب هستند. همچنین برخی از این موجودات ساکن و برخی دیگر دارای حرکت‌اند؛ چنان‌که کوه از جهتی ثابت و از جهتی دیگر دارای حرکت است. موجودات جهان برخی ساکن و برخی متحرک‌اند، پاره‌ای رشد و نمو می‌کنند و پاره‌ای جامد هستند؛ همه را خداوند آفرید و آفرینش او نیز شگفت‌آور بود.\n♦️فَأَقَامَ مِنْ شَوَاهِدِ الْبَینَاتِ عَلَی لَطِیفِ صَنْعَتِهِ، وَعَظِیمِ قُدْرَتِهِ♦️\nخداوند شواهد و دلایل آشکاری (بَیِّنات) بر ظرافت و دقتِ آفرینش و قدرت بی‌کران خود برپا داشت و هنر لطیف و توانایی خود را متجلی ساخت. هنگامی که خداوند موجودات را آفرید، هر یک را شاهدی گویا بر هستی خود قرارداد و به آن‌ها استشهاد و استناد فرمود.\n♦️مَا انْقَادَتْ لَهُ الْعُقُولُ مُعْتَرِفَةً بِهِ، وَمُسَلِّمَةً لَهُ♦️\nچنان‌که تمام خردها و عقول مطیع فرمان او گشتند [انْقَادَتْ]، درحالی‌که به وجود حق‌تعالی اعتراف کرده و در برابر او تسلیم شدند.\n♦️وَ نَقَعَتْ فِی أَسْمَاعِنَا دَلَائِلُهُ عَلَی وَحْدَانِیتِهِ♦️\nخداوند بانگ دلایل یکتایی‌اش را در گوش جان ما طنین‌انداز ساخت [نَقَعَتْ]. خداوند جهانی سراسر ظرافت، دقت و نظم خلق کرده که جلوه‌گاه قدرت اوست؛ پس هنگامی که انسان به این شگفتی‌ها می‌نگرد، عقل باید خاضع شود و عقل در برابر این عظمت فروتنی می‌کند. انسان خردمند با نگریستن به این پدیده‌ها، در برابر حق سر فرود می‌آورد و تعظیم می‌کند. این شگفتی‌ها نه‌تنها بر اصل وجود آفریدگار گواهی می‌دهند، بلکه یگانگی او را نیز به اثبات می‌رسانند.\nاصل وجود خداوند یک مبحث و یگانگی او مبحثی دیگر است. در اثبات یگانگی پروردگار آمده است:\n《 لَوْ کانَ فِیهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا 》\nاگر در جهان دو آفریننده وجود داشت، سراسر هستی دستخوش تباهی می‌شد و موجودات چنین نظم، لطافت و پیوستگی یکپارچه‌ای نداشتند. جهان‌آفرینش زنجیره‌ای متصل است که در آن هر پدیده‌ای به پدیده دیگر وابستگی دارد؛ چنانچه چندخدایی حاکم بود، این رشته از هم می‌گسست؛ بنابراین، سراسر جهان در وهله اول آفریدگار را نمایان می‌سازد و در وهله دوم، توحید و یکتایی او را برای ما اثبات می‌کند.\n♦️وَ مَا ذَرَأَ مِنْ مُخْتَلِفِ صُوَرِ الْأَطْیارِ الَّتِی أَکنَّهَا أَخَادِیدَ الْأَرْضِ، وَخُرُوقَ فِجَاجِهَا، وَرَوَاسِی أَعْلَامِهَا♦️\nو شگفتی دیگر، اشکال و گونه‌های گوناگون پرندگانی است که خداوند آفرید و آن‌ها را از جهات مختلف رده‌بندی نمود. یک دسته‌بندی از حیث زیستگاه است؛ بدین صورت که خداوند صورت‌ها و پیکره‌های متنوعی از پرندگان را آفرید و آن‌ها را در مکان‌های متفاوتی سکنا داد:\n۱- گروهی از پرندگان در شکاف‌ها و اعماق دره‌ها روزگار می‌گذرانند [أَخَادِیدَ الْأَرْضِ] و در سطوح پست و گودی‌های زمین زیست می‌کنند.\n۲- گروهی در دشت‌ها، بیابان‌ها و بسترهای گسترده و پهناور [خُرُوقَ فِجَاجِهَا] و کویرهای وسیع زندگی می‌کنند.\n۳- گروهی دیگر نیز در کوه‌های سرافراز و بلندقامت [رَوَاسِی أَعْلَامِهَا] و بر بلندای ستیغ‌ها و قله‌ها آشیان دارند.\n♦️مِنْ ذَاتِ أَجْنِحَةٍ مُخْتَلِفَةٍ، وَهَیئَاتٍ مُتَبَاینَةٍ♦️\nدسته‌بندی دوم پرندگان بر اساس بال‌ها و پرهای متفاوت آن‌هاست؛ برخی دارای بال‌وپر کمتر و برخی بیشتر، گروهی با پرهای بلند یا کوتاه و پرپشت یا کم‌پشت آفریده شده‌اند. این‌ها پیکره‌ها و شکل‌های متمایزی [هَیئَاتٍ مُتَبَاینَةٍ] هستند که هر کدام متناسب با نیاز زیستی و کیفیت حیات خویش، از بال‌های متناسب و ساختاری مجزا [متباین] برخوردارند.\n♦️مُصَرَّفَةٍ فِی زِمَامِ التَّسْخِیرِ♦️\nیک قاعده کلی درباره پرندگان صادق است و آن اینکه همگی در ید قدرت الهی مقید و مسخرند و مهار پرواز و کنترل این بال‌ها به دست خداست. آفریدگار آن‌ها را خلق فرموده، روزی‌شان را تضمین کرده و جملگی فرمان‌بردار حق هستند؛ چراکه مخلوق‌اند و از آفریدگار خویش فرمان می‌پذیرند.\nمتن‌نویسی: محی‌الدین\n♦️وَ مُرَفْرِفَةٍ بِأَجْنِحَتِهَا فِی مَخَارِقِ الْجَوِّ الْمُنْفَسِحِ، وَالْفَضَاءِ الْمُنْفَرِجِ♦️\nآن‌ها بال‌های خویش را بر فراز آسمان گشوده‌اند [مُرَفْرِفَةٍ] و در هوای باز و فضای بیکران و فراخ [الْمُنْفَسِحِ] پر می‌گشایند و سیر می‌کنند.\nبه تعبیر قرآن کریم در آیه ۷۹ سوره مبارکه نحل:\n(أَلَمْ یرَوْا إِلَی الطَّیرِ مُسَخَّرَاتٍ فِی جَوِّ السَّمَاءِ مَا یمْسِکهُنَّ إِلَّا اللَّهُ إِنَّ فِی ذَلِک لَآیاتٍ لِقَوْمٍ یؤْمِنُونَ)\n«آیا پرندگان رام شده در دل آسمان را ندیده‌اند که هیچ‌کس جز خدا آن‌ها را نگه نمی‌دارد؟ بی‌تردید در این امر نشانه‌هایی برای اهل ایمان نهفته است.»\nحضرت در این خطبه این حقیقت را تبیین می‌فرمایند؛ انسان عاقل حقیقت را درمی‌یابد و قرآن کریم نیز می‌فرماید «یُؤْمِنُونَ»، و روشن است که مؤمنان همان خردمندان راستین هستند.\n♦️کوَّنَهَا بَعْدَ إِذْ لَمْ تَکنْ فِی عَجَائِبِ صُوَرٍ ظَاهِرَةٍ♦️\nخداوند پرندگان را پس از آنکه هیچ نبودند و آثاری از آن‌ها در جهان یافت نمی‌شد، پدید آورد و هر یک را با نقش و نگاری شگفت و صورتی آشکار خلق فرمود؛ شگفتی از جهت زیبایی یا هیبت و دهشت. پاره‌ای پرندگان ظاهری وهم‌انگیز و رعب‌آور دارند و پاره‌ای دیگر بسیار زیبا هستند؛ اما هر یک در نوع خود پدیده‌ای شگفت‌آور به شمار می‌روند و عاری از هرگونه نقص و نارسایی‌اند.\n♦️وَ رَکبَهَا فِی حِقَاقِ مَفَاصِلَ مُحْتَجِبَةٍ♦️\nخداوند اجزای پیکر پرندگان را درون حفره‌ها و بندگاه‌های مفاصل [حِقَاق] پیوند داد [رَکبَهَا]؛ مفاصلی که در پوششی از گوشت نهان و مستور گشته‌اند [مُحْتَجِبَةٍ] تا با قرارگرفتن در میان بافت‌ها، از فرسودگی و خشکی در امان بمانند.\n♦️وَ مَنَعَ بَعْضَهَا بِعَبَالَةِ خَلْقِهِ أَنْ یسْمُوَ فِی الْهَوَاءِ خُفُوفاً♦️\nسومین دسته‌بندی پرندگان پیرامون ساختار بال و شیوه پرواز آن‌هاست. خداوند پرواز اوج‌گیرنده را از گروهی از آنان سلب کرد؛ زیرا پیکری فربه و سنگین دارند [عَبَالَة] و درشتی اندامشان مانع از آن می‌شود که در دل هوا به‌سرعت سبک‌بالی و اوج پرواز را تجربه کنند [یسْمُوَ خُفُوفاً].\n♦️وَ جَعَلَهُ یدِفُّ دَفِیفاً♦️\nو شیوه حرکت آن پرنده را به‌گونه‌ای قرارداد که نزدیک به سطح زمین بال بزند و پروازی کوتاه و چسبیده به زمین داشته باشد.\n♦️وَ نَسَقَهَا عَلَی اخْتِلَافِهَا فِی الْأَصَابِیغِ بِلَطِیفِ قُدْرَتِهِ، وَدَقِیقِ صَنْعَتِهِ♦️\nخداوند با سرانگشت قدرت لطیف و صنعت دقیق خویش، پرندگان را با همه گوناگونی و تفاوت در رنگ‌ها و نگاره‌هایشان [الْأَصَابِیغِ] انتظام و آراستگی بخشید [نَسَقَهَا].\n♦️فَمِنْهَا مَغْمُوسٌ فِی قَالَبِ لَوْنٍ لَا یشُوبُهُ غَیرُ لَوْنِ مَا غُمِسَ فِیهِ♦️\nگونه‌ای از این پرندگان یکدست و تک‌رنگ‌اند (سرتاسر سپید یا سیاه)؛ تو گویی این پرنده در قالبی آکنده از یک‌رنگ فرورفته [مَغْمُوسٌ] و هیچ رنگ دیگری با آن درنیامیخته است [لَا یشُوبُهُ].\n♦️وَ مِنْهَا مَغْمُوسٌ فِی لَوْنِ صِبْغٍ قَدْ طُوِّقَ بِخِلَافِ مَا صُبِغَ بِهِ♦️\nو گونه‌ای دیگر گویی در رنگی خاص فرورفته، درحالی‌که طوقی گردن بندوار [طُوِّقَ] با رنگی متمایز و متضاد، گردن او را آراسته است.\nنگاه حضرت به آفرینش، نگاهی کاملاً توحیدی است:\n– جهان هستی از نظمی شگرف برخوردار است.\n– آفریدگار، جهان را با نهایت ظرافت و ملاحت پدید آورده است.\n– صرفِ نگریستن به خلقت بسنده نیست؛ بلکه حضرت زیبایی‌ها و لطایف نهفته در آفرینش را نیز به تماشا می‌نشیند. پرنده‌ای وجود دارد که آفریدگاری مدبر دارد؛ حضرت تمام جلوه‌های جمال را در او دیده و خاطرنشان می‌سازد که هر آنچه این پرنده بدان نیازمند بوده، خداوند به وی عطا فرموده است. امیرالمؤمنین (ع) دل ما را شیفته و شیدای مخلوقات الهی می‌سازد و هنگامی که انسان به مخلوقات دل بست، به خالق یکتا نیز عشق می‌ورزد. تمام این پدیده‌ها تجلی‌بخش جمال حق هستند؛ پس با تأمل در هستی:\nیک: آفریدگار را بازشناسید.\nدو: توحید و یگانگی او را به نظاره بنشینید.\nسه: جلوه جمال و زیبایی پروردگار را دریابید.\n♦️وَ مِنْ أَعْجَبِهَا خَلْقاً الطَّاوُوسُ الَّذِی أَقَامَهُ فِی أَحْکمِ تَعْدِیلٍ♦️\nو از شگفت‌انگیزترین پرندگان در آفرینش، طاووس است؛ همان پرنده‌ای که خداوند پیکرش را در استوارترین و متناسب‌ترین اعتدال برپا داشت.\n♦️وَ نَضَّدَ أَلْوَانَهُ فِی أَحْسَنِ تَنْضِیدٍ♦️\nو رنگ‌های پرفروغش را در نیکوترین هماهنگی و انتظام [تَنْضِیدٍ] به ترتیب و زیبایی در کنار یکدیگر نشاند [نَضَّدَ].\n♦️بِجَنَاحٍ أَشْرَجَ قَصَبَهُ، وَذَنَبٍ أَطَالَ مَسْحَبَهُ♦️\nبا بال‌هایی که نی‌ها و ساقه‌های پرِ آن را به یکدیگر درآمیخت و پیوند زد [أَشْرَجَ قَصَبَهُ]؛ ساقه‌هایی که از هر یک ده‌ها پرِ زیبا سر برآورده و دُمی بلند [ذَنَبٍ] که بر پهنه زمین کشیده می‌شود.\n♦️إِذَا دَرَجَ إِلَی الْأُنْثَی نَشَرَهُ مِنْ طَیهِ، وَسَمَا بِهِ مُظِلّاً عَلَی رَأْسِهِ♦️\nهنگامی که طاووس نر به‌سوی طاووس ماده گام برمی‌دارد، چتر دُم درهم‌پیچیده خویش را می‌گشاید [نَشَرَهُ مِنْ طَیهِ] و آن را همانند سایبانی برافراشته [مُظِلّاً] بر فراز سرخود به اهتزاز درمی‌آورد.\n♦️کأَنَّهُ قِلْعُ دَارِی عَنَجَهُ نُوتِیهُ♦️\nگویی بادبان [قِلْع] برافراشته کشتی ساخته‌شده در بندر دارین (بندری در بحرین) است؛ این دیار از دو جهت نام‌آشنا بوده است:\n۱- عطر و شمیم دل‌انگیز\n۲- ساخت بادبان‌های کشتی\nازآنجاکه مخاطبان با بندر دارین و بادبان‌های آن آشنایی داشتند، حضرت چتر دُم طاووس را بدان تمثیل فرمود؛ بادبانی که ناخدا آن را پیوسته در جهت باد تنظیم می‌گرداند.\n♦️یخْتَالُ بِأَلْوَانِهِ، وَیمِیسُ بِزَیفَانِهِ♦️\nبه رنگ‌های چشم‌نواز خویش فخر می‌فروشد و با گام‌هایی نازان و خرامان [زَیفَانِهِ] به خود می‌بالد؛ نگاهی به پیکر خویش می‌اندازد و غرور سرتاسر وجودش را فرامی‌گیرد.\n♦️یفْضِی کإِفْضَاءِ الدِّیکةِ♦️\nهمانند خروس [الدِّیکةِ] جفت‌گیری می‌کند [یفْضِی].\n♦️وَ یؤُرُّ بِمُلَاقَحَةٍ أَرَّ الْفُحُولِ الْمُغْتَلِمَةِ لِلضِّرَابِ♦️\nو در آمیزش، مانند نرهای مست و سرکش [الْفُحُولِ الْمُغْتَلِمَةِ] که شهوت وجودشان را فراگرفته، اقدام می‌نماید.\nمتن‌نویسی: محی‌الدین\n♦️أُحِیلُک مِنْ ذَلِک عَلَی مُعَاینَةٍ♦️\nمن تو را در این امر به مشاهده عینی و دیدنِ با چشم ارجاع می‌دهم [أُحِیلُک]؛ مبادا پندارهای نادرست و غیرعلمی دیگران را بپذیرید، بلکه باید شخصاً به مشاهده و پژوهش روی‌آورید.\n♦️لَا کمَنْ یحِیلُ عَلَی ضَعِیفِ إِسْنَادِهِ♦️\nنه مانند کسانی که بر اساس حدس و ادعاهای بی سند و ضعیف سخن می‌گویند و دیگران را به مراجع نامعتبر حواله می‌دهند.\n♦️وَ لَوْ کانَ کزَعْمِ مَنْ یزْعُمُ أَنَّهُ یلْقِحُ بِدَمْعَةٍ تَسْفَحُهَا مَدَامِعُهُ فَتَقِفُ فِی ضَفَّتَی جُفُونِهِ♦️\nاگر سخن کسانی درست باشد که می‌پندارند لقاح طاووس صرفاً با بلعیدن قطره اشکی صورت می‌گیرد که از چشم نر سرازیر شده [تَسْفَحُهَا] و در کناره‌های پلک او [ضَفَّتَی جُفُونِهِ] جا خوش کرده است…\n♦️وَ أَنَّ أُنْثَاهُ تَطْعَمُ ذَلِک ثُمَّ تَبِیضُ لَا مِنْ لَقَاحِ فَحْلٍ سِوَی الدَّمْعِ الْمُنْبَجِسِ♦️\n… و طاووس ماده آن قطره اشک فروریخته را می‌چشد و بی‌آنکه با نر آمیزش کرده باشد، تنها از طریق همان اشکِ جوشیده تخم می‌گذارد و نطفه‌دار می‌شود…\n♦️لَمَا کانَ ذَلِک بِأَعْجَبَ مِنْ مُطَاعَمَةِ الْغُرَابِ♦️\n… این ماجرا شگفت‌انگیزتر از افسانه باردارشدن کلاغ از طریق ترشحات دهان نخواهد بود.\nنکته ۱: چرا حضرت به شیوه آمیزش و لقاح طاووس پرداختند و در میان توصیف زیبایی‌های این پرنده بدان اشاره فرمودند؟ برای‌آنکه افسانه‌ای باطل و خرافی را از اذهان پاک سازند. ما هرگز مجاز نیستیم از مسیری نادرست، حقیقت را اثبات کنیم؛ طاووس نیز مانند سایر موجودات است و در زمره شگفت‌انگیزترین آفریده‌ها قرار دارد. باید در برابر خرافات و پندارهای موهوم هوشیار بود و بر مدار حق و منطق گام برداشت؛ چراکه با توسل به باطل نمی‌توان به حقیقت دست‌یافت.\nنکته ۲: حضرت تأکید فرمودند که کلام انسان باید مستند و دقیق باشد و فرمودند شما را به مشاهده عینی ارجاع می‌دهم. آدمی باید در تمام عرصه‌ها باتکیه‌بر خرد و بینش بیندیشد، سخن بگوید، بنگرد و رفتار کند. منطق و عقل اقتضا می‌کند که فکر، سخن و عمل انسان همواره عاقلانه، مستدل و متکی بر آموزه‌های قرآن و روایات باشد.\nنکته ۳: حضرت در کجا طاووس را مشاهده فرمودند؟ آیا در سرزمین حجاز طاووس وجود داشته است؟ حجاز سرزمینی خشک و کم‌آب و علف بوده، درحالی‌که طاووس بومیِ مناطق معتدل، سرسبز و جنگلی است.\nدر پاسخ به این شبهه، چند وجه بیان شده است:\nابن ابی‌الحدید معتقد است که این خطبه در شهر کوفه ایراد گردیده است؛ کوفه شهری با اقلیم معتدل و سرسبز بوده، موقعیت تجاری و بازرگانی داشته و تردد کاروان‌ها در آن جاری بوده است؛ بنابراین بعید نیست که حضرت طاووس را در بازارهای آن مشاهده کرده باشند یا این پرنده به‌عنوان هدیه برای ایشان آورده شده باشد.\nدیدگاه دیگر این است که مشاهده همواره منحصر در نگاه بصری نیست، بلکه امام معصوم (ع) از علم و بینش باطنی برخوردار بوده و چه از جنبه بصری و چه از جنبه علمی بر حقایق اشراف داشته‌اند.\nدر مجموع، کلام حضرت ما را با معارف توحیدی و زیبایی‌های بی‌بدیل جهان خلقت مأنوس ساخته و دل‌ها را شیفته جلوه‌های جمال پروردگار می‌گرداند.\nاللَّهُمَّ عَجِّلْ لِوَلِیک الْفَرَجَ"," بخش دوم\nمتن:\nتَخَالُ قَصَبَهُ مَدَارِيَ مِنْ فِضَّةٍ وَ مَا أُنْبِتَ عَلَيْهَا مِنْ عَجِيبِ دَارَاتِهِ وَ شُمُوسِهِ خَالِصَ الْعِقْيَانِ وَ فِلَذَ الزَّبَرْجَدِ، فَإِنْ شَبَّهْتَهُ بِمَا أَنْبَتَتِ الْأَرْضُ قُلْتَ [جَنِيٌ] جَنًى جُنِيَ مِنْ زَهْرَةِ كُلِّ رَبِيعٍ، وَ إِنْ ضَاهَيْتَهُ بِالْمَلَابِسِ فَهُوَ كَمَوْشِيِّ الْحُلَلِ أَوْ كَمُونِقِ عَصْبِ الْيَمَنِ، وَ إِنْ شَاكَلْتَهُ بِالْحُلِيِّ فَهُوَ كَفُصُوصٍ ذَاتِ أَلْوَانٍ قَدْ نُطِّقَتْ بِاللُّجَيْنِ الْمُكَلَّلِ، يَمْشِي مَشْيَ الْمَرِحِ الْمُخْتَالِ وَ يَتَصَفَّحُ ذَنَبَهُ وَ [جَنَاحَهُ] جَنَاحَيْهِ فَيُقَهْقِهُ ضَاحِكاً لِجَمَالِ سِرْبَالِهِ وَ أَصَابِيغِ وِشَاحِهِ، فَإِذَا رَمَى بِبَصَرِهِ إِلَى قَوَائِمِهِ زَقَا مُعْوِلًا بِصَوْتٍ يَكَادُ يُبِينُ عَنِ اسْتِغَاثَتِهِ وَ يَشْهَدُ بِصَادِقِ تَوَجُّعِهِ لِأَنَّ قَوَائِمَهُ حُمْشٌ كَقَوَائِمِ الدِّيَكَةِ الْخِلَاسِيَّةِ وَ قَدْ نَجَمَتْ مِنْ ظُنْبُوبِ سَاقِهِ صِيصِيَةٌ خَفِيَّةٌ، وَ لَهُ فِي مَوْضِعِ الْعُرْفِ قُنْزُعَةٌ خَضْرَاءُ مُوَشَّاةٌ وَ مَخْرَجُ عَنُقِهِ كَالْإِبْرِيقِ وَ مَغْرِزُهَا إِلَى حَيْثُ بَطْنُهُ كَصِبْغِ الْوَسِمَةِ الْيَمَانِيَّةِ أَوْ كَحَرِيرَةٍ مُلْبَسَةٍ مِرْآةً ذَاتَ صِقَالٍ وَ كَأَنَّهُ مُتَلَفِّعٌ بِمِعْجَرٍ أَسْحَمَ، إِلَّا أَنَّهُ يُخَيَّلُ لِكَثْرَةِ مَائِهِ وَ شِدَّةِ بَرِيقِهِ أَنَّ الْخُضْرَةَ النَّاضِرَةَ مُمْتَزِجَةٌ بِهِ وَ مَعَ فَتْقِ سَمْعِهِ خَطٌّ كَمُسْتَدَقِّ الْقَلَمِ فِي لَوْنِ الْأُقْحُوَانِ أَبْيَضُ يَقَقٌ فَهُوَ بِبَيَاضِهِ فِي سَوَادِ مَا هُنَالِكَ يَأْتَلِقُ وَ قَلَّ صِبْغٌ إِلَّا وَ قَدْ أَخَذَ مِنْهُ بِقِسْطٍ وَ عَلَاهُ بِكَثْرَةِ صِقَالِهِ وَ بَرِيقِهِ وَ بَصِيصِ دِيبَاجِهِ وَ رَوْنَقِهِ، فَهُوَ كَالْأَزَاهِيرِ الْمَبْثُوثَةِ لَمْ تُرَبِّهَا أَمْطَارُ رَبِيعٍ وَ لَا شُمُوسُ قَيْظٍ وَ قَدْ يَنْحَسِرُ مِنْ رِيشِهِ وَ يَعْرَى مِنْ لِبَاسِهِ فَيَسْقُطُ تَتْرَى وَ يَنْبُتُ تِبَاعاً فَيَنْحَتُّ مِنْ قَصَبِهِ انْحِتَاتَ أَوْرَاقِ الْأَغْصَانِ ثُمَّ يَتَلَاحَقُ نَامِياً حَتَّى يَعُودَ كَهَيْئَتِهِ قَبْلَ سُقُوطِهِ لَا يُخَالِفُ سَالِفَ أَلْوَانِهِ وَ لَا يَقَعُ لَوْنٌ فِي غَيْرِ مَكَانِهِ، وَ إِذَا تَصَفَّحْتَ شَعْرَةً مِنْ شَعَرَاتِ قَصَبِهِ أَرَتْكَ حُمْرَةً وَرْدِيَّةً وَ تَارَةً خُضْرَةً زَبَرْجَدِيَّةً وَ أَحْيَاناً صُفْرَةً عَسْجَدِيَّةً.\nترجمه:\n(هرگاه به بال و پر طاووس بنگرى) گمان مى کنى که نى هاى وسط پرهاى او همچون شانه هايى است که از نقره ساخته شده و آن چه بر آن از حلقه ها و هاله هاى عجيب خورشيد مانند روئيده، طلاى ناب و قطعات زبرجد است! هر گاه بخواهى آن را به آن چه زمين (به هنگام بهار) مى روياند تشبيه کنى، مى گويى دسته گلى است که از شکوفه هاى گل هاى بهارى چيده شده (و با نظم خاصى در کنار هم قرار گرفته است) و اگر بخواهى آن را به لباس ها (و پرده هاى رنگارنگ) تشبيه کنى، همچون حله هاى زيباى پر نقش و نگار يا پرده هاى رنگارنگ يمنى است و اگر آن را با زيورها مقايسه کنى، همچون نگين هاى رنگارنگى است که در نوارى از نقره که با جواهرات، زينت يافته در تاجى قرار گرفته است.\nاو همچون کسى که به خود مى بالد با عشوه و ناز گام بر مى دارد; گاه سر را بر مى گرداند و به دم (زيبا) و دو بالش مى نگرد; ناگهان از زيبايى فوق العاده اى که پر وبالش به او بخشيده و رنگ هايى که همچون لؤلؤ و جواهر به هم درآميخته قهقهه سر مى دهد; اما همين که (خم مى شود و به) پاهاى (زشت) خود نظر مى افکند آن چنان (ناراحت مى گردد که) صداى گريه او بلند مى شود; فريادى که استغاثه جان کاهش از آن آشکار است و گواه صادق دردى است که در درون دارد! چه اين که پاهايش همچون پاهاى خروس خلاسى باريک (و تيره رنگ و زشت) است و در گوشه اى از ساق پايش ناخنى مخفى روييده شده.\nاو در محل يال خود، کاکلى دارد; سبزرنگ و پر نقش و نگار و انتهاى گردنش همچون ابريق است و از گلوگاه تا روى شکمش به رنگ وسمه يمانى (سبز پررنگ مايل به سياهى) و گاه همچون حريرى است که در بر کرده و مانند آينه صيقلى شده مى درخشد، گويى بر اطراف گردنش معجرى است سياه رنگ که به خود پيچيده; ولى از کثرت شادابى و درخشندگى به نظر مى رسد که رنگ سبز پرطراوتى با آن آميخته شده و در کنار گوشش خط باريک بسيار سفيدى همچون نيش قلم به رنگ گل بابونه کشيده شده که بر اثر سفيدى درخشنده اش در ميان آن سياهى تلألؤ خاصّى دارد. کمتر رنگى (در جهان) يافت مى شود که طاووس از آن بهره اى نگرفته باشد; با اين فرق که شفافيّت و درخشندگى و تلألؤ حرير مانند رنگ پرهاى او بر تمام رنگ هاى برترى دارد و (در واقع) همانند شکوفه هاى زيباى پراکنده گل هاست; با اين تفاوت که نه باران بهارى آن را پرورش داده و نه حرارت و تابش آفتاب تابستان!\nگاه او (طاووس) از پرهايش بيرون مى آيد و لباسش را از تن خارج مى کند. (آرى) پرهاى او پى در پى و به دنبال آن پشت سر هم مى رويند. پويش پرها، از نى آن ها، همچون ريزش برگ ها از شاخه ها (در فصل پاييز) فرو مى ريزد، سپس رشد و نمو مى کند، تا بار ديگر به شکل نخست درآيد (با اين حال) با رنگ هاى سابق هيچ تفاوتى پيدا نمى کنند و رنگى به جاى رنگ ديگر نمى نشيند. اگر تارى از تارهاى پر او را بررسى کنى گاه سرخ گلرنگ را به تو نشان مى دهد وگاه رنگ سبز زبرجدى و زمانى زرد طلايى (و هر يک جلوه خاص خود را دارد).\nتفسیر:\n در بخش ابتدایی، حضرت به حکمت الهی می‌پردازند مبنی بر اینکه هر امری که از خداوند صادر می‌شود هدفمند است؛ البته غایت و هدف این امور، رشد خداوند نیست، چراکه او کمال مطلق است، بلکه غرضْ تکامل و پرورش انسان است.\n🔷یدَّعِی بِزَعْمِهِ أَنَّهُ یرْجُو اللَّهَ🔷\nانسان به پندار و گمان خود ادعا می‌کند که به خداوند امیدوار است. این بخش پیرامون خوف‌ورجا سخن می‌گوید؛ شخصی گمان می‌برد که به خدا امید دارد.\n🔷کذَبَ وَالْعَظِیمِ🔷\nسوگند به خدای بزرگ که دروغ می‌گوید؛ چنین نیست که امیدواری تنها یک ادعا باشد. «الْبَینَةُ عَلَی الْمُدَّعِی»؛ هر کس ادعایی دارد باید بر آن دلیل اقامه کند.\n🔷مَا بَالُهُ لَا یتَبَینُ رَجَاؤُهُ فِی عَمَلِهِ؟🔷\nاین شخص را چه شده است که نشان این امیدواری در کردارش نمایان نیست؟ هنگامی که ادعای رجا می‌کند، باید در عمل نیز نشانه‌ای آشکار باشد.\n🔷فَکلُّ مَنْ رَجَا عُرِفَ رَجَاؤُهُ فِی عَمَلِهِ، إِلَّا رَجَاءَ اللَّهِ تَعَالَی فَإِنَّهُ مَدْخُولٌ🔷\nهر کس به چیزی امید بندد، امیدواری‌اش در کردار او شناخته می‌شود، مگر امید به خدای متعال که ناسالم و آمیخته با فریب [مَدْخُولٌ] است. به تعبیر قرآن کریم: «فَمَنْ کانَ یرْجُو لِقَاءَ رَبِّهِ فَلْیعْمَلْ عَمَلًا صَالِحًا» (کهف/۱۱۰)؛ اگر کسی امید به لقای پروردگار دارد، باید عمل صالح به جا آورد و صرفِ ادعا کفایت نمی‌کند. دلیل و برهان این ادعا چیست؟ شخص امیدوار به خدا باید امیدش در عمل هویدا باشد، حال‌آنکه در عمل، نشانه‌ای از رجا و امیدواری در ما مشاهده نمی‌شود.\nتعبیر حضرت این است که اگر به‌راستی خواهان نیل به مرتبه رجا هستید، باید آثاری در کردارتان پدیدار گردد. در اصول کافی (جلد ۲، صفحه ۶۸، باب خوف‌ورجا) آمده است:\n«قُلْتُ لَهُ قَوْمٌ یعْمَلُونَ بِالْمَعَاصِی وَ یقُولُونَ نَرْجُو…»؛ به امام معصوم (ع) عرض شد گروهی پیوسته مرتکب گناه می‌شوند و می‌گویند ما به رحمت خدا امیدواریم و بر این ادعا پافشاری می‌کنند تا اینکه مرگشان فرامی‌رسد. امام (ع) فرمودند: آنان گروهی هستند که تنها ادعای امیدواری دارند و در پی آرزوهای باطل‌اند؛ اینان هرگز امیدوار واقعی نیستند. اگر انسان حقیقتاً امیدوار باشد، به عمل صالح روی می‌آورد. چنین نیست که اهل‌بیت (ع) سپر و پوششی برای گناهان ما باشند تا ما پیوسته گناه کنیم و مدام طلب بخشش نماییم.\nهرچند اثر ذاتی توسل و گریستن بر مصائب اهل‌بیت (ع) پاک‌کننده گناهان است، اما نباید دستاویز تکرار معصیت قرار گیرد تا امام حسین (ع) ما را شفاعت کند؛ این نگرش، امیدواری حقیقی نیست بلکه فریبی بیش نیست.\nاگر آدمی از چیزی بهراسد از آن می‌گریزد؛ چگونه است که از عذاب گناه بیم داریم؛ اما از خودِ گناه دوری نمی‌گزینیم یا عملی که خشنودی حق در آن است انجام نمی‌دهیم؟\n🔷فَکلُّ مَنْ رَجَا عُرِفَ رَجَاؤُهُ فِی عَمَلِهِ، إِلَّا رَجَاءَ اللَّهِ فَإِنَّهُ مَدْخُولٌ🔷\nهر کس ادعای امید به خدا دارد، باید این امیدواری در کردارش متجلی گردد؛ هر امیدی که خالی از اخلاص برای خدا باشد، نادرست و آمیخته به فساد [مَدْخُول] است. امیدبستن به غیر خدا باطل و گمراهی است.\nآن که دارای قدرت و دانش مطلق است تنها پروردگار است، و خداوند خود مسیر را نمایان ساخته است؛ یعنی توسل‌جستن به انوار مقدس چهارده‌معصوم (ع) برای گشایش امور. امید راستین باید به خداوند باشد و توکل بر هر کس جز او، خواه تکیه بر خود، دانش، توانایی یا جوانی، پیمودن راه خطاست.\n🔷وَکلُّ خَوْفٍ مُحَقَّقٌ، إِلَّا خَوْفَ اللَّهِ فَإِنَّهُ مَعْلُولٌ🔷\nهر ترسی که به مرحله وقوع و حقیقت برسد [مُحَقَّقٌ]، اثرش هویداست مگر ترس از خدا که بیمارگونه و ناقص [مَعْلُولٌ] است. امید داشتن به غیر خدا باطل و واهی است و ترس از غیر او نیز هراسی بی‌پایه است. در آموزه‌های دشمن‌شناسی اهل‌بیت (ع) آمده است که دشمن را بشناسید، ارزیابی کنید و نقشه‌های او را خنثی سازید؛ دشمن را ببینید؛ اما از او نهراسید. حضرت فرمودند بیم از هر کس جز خدا نادرست است.\nآرامش حقیقی در توحید و تکیه بر ذات اقدس الهی نهفته است. امام صادق (ع) فرمودند از فتنه‌ها نهراسید؛ هرچند در کوران فتنه‌ها شهادت، جانبازی و سختی‌ها پدید می‌آید، اما سرانجامْ همه این‌ها خیر و رحمت است. تعبیر امیرالمؤمنین (ع) در حکمت ۸۲ نهج‌البلاغه این است که شما را به پنج امر وصیت می‌کنم که اگر برای دستیابی به آن‌ها روزهای متمادی شتران را به‌شتاب برانید و رنج سفر بکشید، ارزش آن را دارد:\n«لَا یرْجُوَنَّ أَحَدٌ مِنْکمْ إِلَّا رَبَّهُ»؛ هیچ‌یک از شما جز به پروردگار خود امید نبندد.\n«وَ لَا یخَافَنَّ إِلَّا ذَنْبَهُ»؛ و از هیچ‌چیز جز گناه خویش نهراسد.\n🔷یرْجُو اللَّهَ فِی الْکبِیرِ، وَیرْجُو الْعِبَادَ فِی الصَّغِیرِ🔷\nپاره‌ای از مردم بیراهه می‌روند و به‌جای بیم و امید از خداوند، به بندگان چشم می‌دوزند.\nدر تذکر دوم می‌فرماید اینان امیدی ناقص به پروردگار دارند و امیدشان کامل نیست؛ در پاره‌ای از امور به خدا دل می‌بندند و در اموری دیگر به پدر و رئیس تکیه دارند.\nبرخی انسان‌ها در امور خطیر و بزرگ نظیر بهشت و جهنم و گرفتاری‌های سترگ به خدا امید دارند، اما در امور خرد و کوچک به مردم، درآمد و دوستان چشم امید می‌دوزند که این همان امیدبستن به غیر خداست.\n🔷فَیعْطِی الْعَبْدَ مَا لَا یعْطِی الرَّبَّ🔷\nنسبت به بندگان چنان فروتنی و خشوع به خرج می‌دهد [یعْطِی] که در پیشگاه خداوند چنین نمی‌کند؛ در کاری خرد در برابر مخلوق چنان بندگی می‌کند که در برابر تمامی نعمت‌های الهی چنین کرنشی به جا نمی‌آورد.\nاین رفتار نخستْ شائبه شرک دارد؛ چراکه دل‌بستن به غیر خداست، و دوم آنکه فروتنی در برابر مخلوق بیش از خضوع در برابر پروردگار است.\n🔷فَمَا بَالُ اللَّهِ جَلَّ ثَنَاؤُهُ یقَصَّرُ بِهِ عَمَّا یصْنَعُ بِهِ لِعِبَادِهِ🔷\nچگونه است که حق خداوند متعال کمتر از حق بندگان رعایت می‌شود؟ چرا در حق پروردگار کوتاهی می‌کنیم؛ اما از بندگان دریغ نمی‌ورزیم؟ چه شده است که عظمت حق را چنان کوچک می‌شماریم که حاضر نیستیم در برابرش فروتنی کنیم و به وظیفه بندگی عمل نماییم؟\n🔷أَتَخَافُ أَنْ تَکونَ فِی رَجَائِک لَهُ کاذِباً؟🔷\nآیا بیم داری که در امیدواری‌ات به او دروغگو باشی؟ این سخن را دو وجه است:\nنخست آنکه آیا می‌ترسی خداوند امیدت را واهی انگارد و دست رد به سینه‌ات زند؟\nوجه دوم: شاید خداوند را رحمان و رحیم نمی‌دانی که این نقصی در باورهای توحیدی است و شاید پروردگار را صرفاً منتقم می‌پنداری.\nدر هر دو حالتْ چنین اندیشه‌ای نادرست است؛ امید باید تنها به خدا معطوف باشد و باید در برابر الطاف او سر تسلیم فرود آورد.\n🔷أَوْ تَکونَ لَا تَرَاهُ لِلرَّجَاءِ مَوْضِعاً؟🔷\nیا اینکه خداوند را شایسته رجا و امیدواری نمی‌دانی و او را سزاوار این توکل نمی‌پنداری؟ درحالی‌که قدرت، دانش و رحمت بی‌کران جملگی در حیطه اراده اوست و تنها باید از درگاه او طلب کرد.\n🔷وَکذَلِک إِنْ هُوَ خَافَ عَبْداً مِنْ عَبِیدِهِ، أَعْطَاهُ مِنْ خَوْفِهِ مَا لَا یعْطِی رَبَّهُ🔷\nدر باب ترس نیز چنین است؛ اگر از بنده‌ای از بندگان خدا بهراسد، چنان ترسی نسبت به او ابراز می‌دارد و کرنشی به‌جای می‌آورد که هرگز نظیر آن را در پیشگاه پروردگار خویش انجام نداده است. بسا هراس‌هایی از مردم و عقب‌نشینی‌ها از مسیر حق که وجود دارد، درحالی‌که چنین خوفی از آفریدگار نیست؛ خدایی که قادر است در همان آنْ جان و مال را بستاند و آدمی را به عذاب دوزخ دچار سازد.\n🔷فَجَعَلَ خَوْفَهُ مِنَ الْعِبَادِ نَقْداً، وَخَوْفَهُ مِنْ خَالِقِهِ ضِمَاراً وَوَعْداً🔷\nبدین‌سان ترس خود از بندگان را نقدی و فوری دانسته، از بیم آنکه مبادا مردم بی‌درنگ از او انتقام گیرند، ولی ترس از آفریدگار خویش را وعده‌ای دوردست و نسیه‌ای غیرقابل‌وصول [ضِمَاراً وَوَعْداً] انگاشته است.\nتأکید حضرت بر این است که هرگز مرگ را دور مپندارید؛ حضرت می‌فرمایند تو گویی صور دوم دمیده شده و پای به رستاخیز نهاده‌اید؛ مرگ چنان نزدیک است که گویی فرارسیده، لیکن ما از آن غافل مانده‌ایم.\n🔷وَکذَلِک مَنْ عَظُمَتِ الدُّنْیا فِی عَینِهِ، وَکبُرَ مَوْقِعُهَا مِنْ قَلْبِهِ🔷\nهمچنین هر کس دنیا در دیدگانش سترگ جلوه کند و منزلت و جایگاه آن [مَوْقِعُهَا] در دلش بزرگ شود…\n🔷آثَرَهَا عَلَی اللَّهِ تَعَالَی🔷\nدنیا را بر ذات اقدس پروردگار برمی‌گزیند و آن را مقدم می‌دارد [آثَرَ]؛ چراکه دنیا در نظرش عظیم گشته است.\nدر بیانی دیگر حضرت فرمود: درگذشته برادری الهی داشتم که در چشم من بزرگ می‌نمود، زیرا دنیا در چشم او خوار و کوچک شده بود. مؤمنان راستین دنیا را حقیر می‌شمارند و قرآن کریم نیز می‌فرماید متاع دنیا اندک و ناچیز است، لیکن آنان که تنها ادعای رجا دارند و در پیشگاه مردم سر فرود می‌آورند، دنیا را سترگ می‌انگارند.\n🔷فَانْقَطَعَ إِلَیهَا، وَصَارَ عَبْداً لَهَا🔷\nچنین کسی سراسر پیوند خود را به دنیا اختصاص می‌دهد و بنده آن می‌گردد.\nما در مناجات شعبانیه چنین تقاضا می‌کنیم: «إِلَهِی هَبْ لِی کمَالَ الِانْقِطَاعِ إِلَیک»؛ یعنی خداوندا گسستن تام از ما سوی و پیوستن به بارگاه خودت را به ما ارزانی دار.\nدر تاریخ، کسانی همچون عمر سعد دیدگاهی دنیامدارانه داشتند و تمام دغدغه‌شان در تعلقات دنیوی خلاصه می‌شد؛ بر سر دوراهی شهادت امام حسین (ع) و دستیابی به مُلک ری، فرمانروایی ری را برگزیدند. در ابیاتی منسوب به عمر سعد در این تزلزل آمده است: دنیا نقد و حاضر است و کدام عاقل نقد را به نسیه وامی‌گذارد؟ بهشت کجاست؟ هنگامی که سودای دنیا جان را فراگیرد، آدمی حتی حسین بن علی (ع) را به مسلخ می‌برد تا به دنیا دست یابد. لیکن در مکتب نبوی آمده است: «الدُّنْیا دَارُ مَنْ لَا دَارَ لَهُ»؛ دنیا خانه کسی است که خانه‌ای جاودان ندارد، «وَ لَهَا یجْمَعُ مَنْ لَا عَقْلَ لَهُ»؛ و برای آن کسی مال گرد می‌آورد که از خرد بی‌بهره است.\nاین دو مکتب در تقابل‌اند؛ با بینش مادی‌گرایانه، حسین (ع) برای دستیابی به مطامع دنیوی به شهادت می‌رسد، اما در مکتب وحی، پیامبر گرامی اسلام (ص) اسوه زاهدان و وارستگان می‌گردد.\n🔷وَلَقَدْ کانَ فِی رَسُولِ اللَّهِ صَلَّی اللَّهُ عَلَیهِ وَآلِهِ کافٍ لَک فِی الْأُسْوَةِ🔷\nبی‌تردید وجود پیامبر خدا (ص) در الگوپذیری و اسوه بودن برای تو بسنده است. انسان همواره ناگزیر از الگوپذیری است؛ حتی رسول‌الله (ص) نیز از طریق وحی با پروردگار مرتبط بود و تعالیم آسمانی را دریافت می‌نمود. سیره پیامبر برای الگو بودن تو کفایت می‌کند، پس نگاهت همواره به رسول خدا باشد.\n🔷وَدَلِیلٌ لَک عَلَی ذَمِّ الدُّنْیا وَعَیبِهَا🔷\nو او برای تو راهنما و دلیلی است بر نکوهش دنیا و نمایان ساختن عیوب آن؛ به سیره پیامبر بنگرید تا حقیقتِ ناچیز دنیا در نظرتان آشکار گردد.\nتفاوت اسوه و دلیل در این است که اسوه الگویی است که ما باید به‌سوی او گام برداریم و دلیل راهنمایی است که ما را به‌سوی خود فرامی‌خواند؛ رسول‌الله (ص) هم اسوه است که باید به او اقتدا کنیم و هم دلیل و هادی است که پیوسته ما را به حق دعوت می‌فرماید.\n🔷وَکثْرَةِ مَخَازِیهَا وَمَسَاوِیهَا🔷\nو دلیلی است بر کثرت رسوایی‌ها [مَخَازِی] و پلیدی‌های [مَسَاوِی] این جهان گذران.\n🔷إِذْ قُبِضَتْ عَنْهُ أَطْرَافُهَا، وَوُطِّئَتْ لِغَیرِهِ أَکنَافُهَا🔷\nبنگرید که چگونه نعمت‌های دنیا از پیرامون پیامبر برچیده شد و خوانِ دنیا از برابرش جمع گردید، درحالی‌که اطراف‌واکناف آن برای دیگران هموار و رام گشت [وُطِّئَتْ]؛ چراکه خداوند پیامبرش را دوست می‌داشت و دنیاطلبی را از ساحت او دور گردانید.\n🔷وَفُطِمَ عَنْ رَضَاعِهَا، وَزُوِی عَنْ زَخَارِفِهَا🔷\nو پیامبر از شیرِ فریبنده این دنیا گرفته شد [فُطِمَ]؛ دنیا برای عده‌ای همچون مادری است که آنان را شیر می‌دهد و پرورش مادی می‌بخشد، لیکن برای پیامبر اکرم (ص) تمامی زر و زیورها [زَخَارِف] از دسترس دورگشت.\n🔷وَإِنْ شِئْتَ ثَنَّیتَ بِمُوسَی کلِیمِ اللَّهِ صَلَّی اللَّهُ عَلَیهِ🔷\nو اگر بخواهی، دومین نمونه را حضرت موسی کلیم‌الله (ع) قرار می‌دهم تا جلوه زهد و بی‌اعتنایی به دنیا آشکار شود.\n🔷حَیثُ یقُولُ \"رَبِّ إِنِّی لِمَا أَنْزَلْتَ إِلَی مِنْ خَیرٍ فَقِیرٌ\"🔷\nآن هنگام که به پیشگاه الهی عرضه داشت: «پروردگارا! من به هر خیری که بر من فرو فرستی نیازمندم» (قصص/۲۴).\nموسی کلیم با فرعونیان درگیر شد و در دفاع از مظلوم، ضربه‌ای فرود آورد که به مرگ فرد مهاجم انجامید؛ سپس او را تعقیب کردند و جناب موسی بی‌آنکه هویت خویش را آشکار سازد از مصر گریخت. او در طول مسیر تنها از گیاهان صحرا تغذیه می‌کرد و مسیر مصر به شام را پیمود تا به مدین رسید. در آنجا ماجرای دختران شعیب پیش آمد و پس از آنکه برای آنان از چاه آب کشید، عرض کرد: پروردگارا! من گرفتار و نیازمند فضل تو هستم. آیا می‌دانید اوج زهد موسی در چه بود؟\n🔷وَاللَّهِ مَا سَأَلَهُ إِلَّا خُبْزاً یأْکلُهُ🔷\nسوگند به خدا هنگامی که موسی این حاجت را به درگاه پروردگار برد، تنها قرص نانی [خُبْزاً] می‌طلبید تا با آن سد جوع کند؛ باوجود تحمل آن همه رنج و مشقت، تنها طعام یک وعده را خواست و این است معنای زهد موسی.\n🔷لِأَنَّهُ کانَ یأْکلُ بَقْلَةَ الْأَرْضِ🔷\nچراکه او در آن مدت تنها از گیاهان خودروی زمین ارتزاق می‌کرد.\n🔷وَلَقَدْ کانَتْ خُضْرَةُ الْبَقْلِ تُرَی مِنْ شَفِیفِ صِفَاقِ بَطْنِهِ، لِهُزَالِهِ وَتَشَذُّبِ لَحْمِهِ🔷\nآن‌قدر گیاه صحرایی خورده بود که سرسبزی علف‌ها از پشت پوست‌نازک شکمش [صِفَاقِ بَطْنِهِ] نمایان بود، چراکه به دلیل سختی راه و گرسنگی به‌شدت لاغر [هُزَال] و تکیده گشته بود [تَشَذُّبِ لَحْمِهِ].\nهنگامی که موسی به فقر خویش اقرار کرد، خداوند فرمود: «یا مُوسَی، الْفَقِیرُ مَنْ لَیسَ مِثْلِی کفِیلٌ»؛ ای موسی! فقیر واقعی کسی است که سرپرست و کفیلی چون من نداشته باشد.\n🔷وَإِنْ شِئْتَ ثَلَّثْتَ بِدَاوُدَ صَلَّی اللَّهُ عَلَیهِ، صَاحِبِ الْمَزَامِیرِ وَقَارِئِ أَهْلِ الْجَنَّةِ🔷\nو اگر بخواهی، سومین نمونه را داوود پیامبر (ع) قرار می‌دهم؛ همو که صاحب مزامیر (کتاب زبور و مناجات‌ها) و نغمه‌خوان اهل بهشت است. در روایات آمده که چون داوود لب به تلاوت مزامیر می‌گشود، پرندگان و وحوش گرد او حلقه می‌زدند. او در سرای دیگر نیز نغمه‌خوان بهشتیان است، زیرا صدایی بس دل‌انگیز داشت؛ زهد او در چه نمود داشت؟\n🔷فَلَقَدْ کانَ یعْمَلُ سَفَائِفَ الْخَوْصِ بِیدِهِ🔷\nداوود نبی با دستان خویش زنبیل‌ها و بافته‌هایی از برگ خرما فراهم می‌ساخت و پیشه‌اش این بود. قرآن مجید درباره او می‌فرماید: «وَشَدَدْنَا مُلْکهُ وَآتَینَاهُ الْحِکمَةَ وَفَصْلَ الْخِطَابِ» (ص/۲۰). با اینکه حضرت داوود پادشاهی و فرمانروایی داشت، اما پیش از حکومت و در دوران آن، از طریق حصیربافی روزی می‌گذراند. او برای خود چیزی از بیت‌المال نمی‌خواست، اما به درگاه خدا عرضه داشت که مردم و فقرا نیازمندند؛ پس خداوند اراده فرمود: «وَأَلَنَّا لَهُ الْحَدِیدَ» (سبأ/۱۰) و آهن در دستان او چون موم نرم گردید؛ بدین ترتیب زره می‌بافت، می‌فروخت و به مستمندان انفاق می‌کرد.\n🔷وَیقُولُ لِجُلَسَائِهِ: أَیکمْ یکفِینِی بِبَیعِهَا؟🔷\nو همواره به همنشینان خویش می‌فرمود: کدام‌یک از شما به نیابت از من این بافته‌ها را می‌فروشد؟\nعبارت «أَیکمْ یکفِینِی بِبَیعِهَا» متضمن دو نکته است:\nیک: حضرت داوود در پی کارآفرینی بود و بافتن حصیر و زره را به دیگران می‌سپرد تا زمینه‌ای برای فعالیت اقتصادی آنان فراهم سازد؛ این سیره اقتصادی انبیا بود.\nدو: داوود نبی خود به بازار نمی‌رفت، چراکه در مقام حاکم، ممکن بود مردم کالا را به بهای گزاف‌تر بخرند و سپس توقعاتی نابجا داشته باشند؛ ازاین‌رو برای زدودن هرگونه شائبه و برقراری عدالت کامل، فروش کالا را به دیگران می‌سپرد.\n🔷وَیأْکلُ قُرْصَ الشَّعِیرِ مِنْ ثَمَنِهَا🔷\nو از بهای آن بافته‌ها، قرص نان جوینی فراهم می‌کرد و از حاصل دسترنج خویش می‌خورد.\n🔷وَإِنْ شِئْتَ قُلْتُ فِی عِیسَی ابْنِ مَرْیمَ عَلَیهِ السَّلَامُ🔷\nو اگر بخواهی، چهارمین الگو عیسی بن مریم (ع) است که سرگذشتش را بازگو می‌کنم.\n🔷فَلَقَدْ کانَ یتَوَسَّدُ الْحَجَرَ🔷\nعیسی بن مریم سنگی را بالش زیر سرخود قرار می‌داد [یتَوَسَّدُ].\n🔷وَیلْبَسُ الْخَشِنَ، وَیأْکلُ الْجَشِبَ🔷\nجامه‌های زبر و خشن بر تن می‌کرد و خوراک خشک و بی‌تکلّف [الْجَشِبَ] می‌خورد.\nعبدالله بن عباس نقل می‌کند که امیرالمؤمنین علی (ع) نانی خشک با خود داشت که حتی شکستنش با دست دشوار بود چه رسد با دندان؛ این رفتار، سیروسلوک معصومان در مسیر زهد را نمایان می‌سازد.\n🔷وَکانَ إِدَامُهُ الْجُوعَ، وَسِرَاجُهُ بِاللَّیلِ الْقَمَرَ🔷\nخورشِ طعام او [إِدَامُهُ] گرسنگی بود. پاره‌ای مفسران گفته‌اند آن‌چنان با فواصل طولانی غذا تناول می‌کرد که در اوج گرسنگی، هر خوراک ساده‌ای برایش مطبوع‌ترین غذا به شمار می‌رفت. معنای دیگر آنکه لذت او در سبک‌بالی و گرسنگی بود؛ چراغ روشنایی‌بخش او در دل تاریکی شب، مهتاب بود.\n🔷وَظِلَالُهُ فِی الشِّتَاءِ مَشَارِقَ الْأَرْضِ وَمَغَارِبَهَا🔷\nسرپناه و سایبان او [ظِلَالُهُ] در سرمای زمستان، پهنه خاور و باخترزمین بود؛ بامدادان رو به‌سوی مشرق آفتاب می‌گرفت و شامگاهان رو به‌سوی مغرب.\n🔷وَفَاکهَتُهُ وَرَیحَانُهُ مَا تُنْبِتُ الْأَرْضُ لِلْبَهَائِمِ🔷\nمیوه و سبزیجات معطر او همان گیاهانی بود که از زمین برای چارپایان می‌رویید.\n🔷وَلَمْ تَکنْ لَهُ زَوْجَةٌ تَفْتِنُهُ، وَلَا وَلَدٌ یحْزُنُهُ🔷\nنه همسری داشت که او را بفریبد و به خود مشغول دارد [تَفْتِنُهُ]، و نه فرزندی که اندوهی بر دلش نشاند.\n🔷وَلَا مَالٌ یلْفِتُهُ، وَلَا طَمَعٌ یذِلُّهُ🔷\nنه ثروتی داشت که توجهش را جلب کند [یلْفِتُهُ]، و نه طمعی که او را به ورطه خواری و ذلت بکشاند.\nداشتن تعلقات مادی همواره رنج آفرین است؛ پس اگر چیزی از متاع دنیا در اختیارتان نیست اندوهگین مباشید. عیسی (ع) به کمالی از زهد دست‌یافته بود که هرگز طمعی در دل نداشت.\n🔷دَابَّتُهُ رِجْلَاهُ، وَخَادِمُهُ یدَاهُ🔷\nمرکب سواری‌اش [دَابَّتُهُ] دو پای او و خدمتکارش دستانش بودند؛ تمامی کارهایش را خود شخصاً انجام می‌داد.\nامیرالمؤمنین (ع) فرمود: «أَشْرَفُ الْغِنَی تَرْک الْمُنَی»؛ والاترین توانگری، رهاکردن آرزوهای دورودراز است. عیسی (ع) به والاترین مرتبه توانگری معنوی نائل شده بود. گاه آدمی مال فراوان دارد؛ اما در باطن فقیر است؛ زهد راستین هنگامی ارزش دارد که با بی‌نیازی دل همراه باشد.\nبنابراین، باید بیم و امید حقیقی را در دل پروراند و نسبت به زرق‌وبرق دنیا بی‌اعتنا بود، چراکه الگوهایی کامل و راستین پیشروی ماست.\nاللَّهُمَّ اجْعَلْ عَوَاقِبَ أُمُورِنَا خَیراً","بخش سوم\nمتن:\nفَكَيْفَ تَصِلُ إِلَى صِفَةِ هَذَا عَمَائِقُ الْفِطَنِ أَوْ تَبْلُغُهُ قَرَائِحُ الْعُقُولِ أَوْ تَسْتَنْظِمُ وَصْفَهُ أَقْوَالُ الْوَاصِفِينَ وَ أَقَلُّ أَجْزَائِهِ، قَدْ أَعْجَزَ الْأَوْهَامَ أَنْ تُدْرِكَهُ وَ الْأَلْسِنَةَ أَنْ تَصِفَهُ. فَسُبْحَانَ الَّذِي بَهَرَ الْعُقُولَ عَنْ وَصْفِ خَلْقٍ جَلَّاهُ لِلْعُيُونِ، فَأَدْرَكَتْهُ مَحْدُوداً مُكَوَّناً وَ مُؤَلَّفاً مُلَوَّناً، وَ أَعْجَزَ الْأَلْسُنَ عَنْ تَلْخِيصِ صِفَتِهِ وَ قَعَدَ بِهَا عَنْ تَأْدِيَةِ نَعْتِهِ.\nصِغارُ المخلوقات:\nوَ سُبْحَانَ مَنْ أَدْمَجَ قَوَائِمَ الذَّرَّةِ وَ الْهَمَجَةِ، إِلَى مَا فَوْقَهُمَا مِنْ خَلْقِ الْحِيتَانِ وَ الْفِيَلَةِ؛ وَ وَأَى عَلَى نَفْسِهِ أَلَّا يَضْطَرِبَ شَبَحٌ مِمَّا أَوْلَجَ فِيهِ الرُّوحَ، إِلَّا وَ جَعَلَ الْحِمَامَ مَوْعِدَهُ وَ الْفَنَاءَ غَايَتَهُ.\nمِنها في صفة الجنّة:\nفَلَوْ رَمَيْتَ بِبَصَرِ قَلْبِكَ نَحْوَ مَا يُوصَفُ لَكَ مِنْهَا لَعَزَفَتْ نَفْسُكَ عَنْ بَدَائِعِ مَا أُخْرِجَ إِلَى الدُّنْيَا مِنْ شَهَوَاتِهَا وَ لَذَّاتِهَا وَ زَخَارِفِ مَنَاظِرِهَا، وَ لَذَهِلَتْ بِالْفِكْرِ فِي [اصْطِفَافِ] اصْطِفَاقِ أَشْجَارٍ غُيِّبَتْ عُرُوقُهَا فِي كُثْبَانِ الْمِسْكِ عَلَى سَوَاحِلِ أَنْهَارِهَا وَ فِي تَعْلِيقِ كَبَائِسِ اللُّؤْلُؤِ الرَّطْبِ فِي عَسَالِيجِهَا وَ أَفْنَانِهَا وَ طُلُوعِ تِلْكَ الثِّمَارِ مُخْتَلِفَةً فِي غُلُفِ أَكْمَامِهَا تُجْنَى مِنْ غَيْرِ تَكَلُّفٍ، فَتَأْتِي عَلَى مُنْيَةِ مُجْتَنِيهَا وَ يُطَافُ عَلَى نُزَّالِهَا فِي أَفْنِيَةِ قُصُورِهَا بِالْأَعْسَالِ الْمُصَفَّقَةِ وَ الْخُمُورِ الْمُرَوَّقَةِ، قَوْمٌ لَمْ تَزَلِ الْكَرَامَةُ تَتَمَادَى بِهِمْ حَتَّى حَلُّوا دَارَ الْقَرَارِ وَ أَمِنُوا نُقْلَةَ الْأَسْفَارِ. فَلَوْ شَغَلْتَ قَلْبَكَ أَيُّهَا الْمُسْتَمِعُ بِالْوُصُولِ إِلَى مَا يَهْجُمُ عَلَيْكَ مِنْ تِلْكَ الْمَنَاظِرِ الْمُونِقَةِ، لَزَهِقَتْ نَفْسُكَ شَوْقاً إِلَيْهَا وَ لَتَحَمَّلْتَ مِنْ مَجْلِسِي هَذَا إِلَى مُجَاوَرَةِ أَهْلِ الْقُبُورِ اسْتِعْجَالًا بِهَا. جَعَلَنَا اللَّهُ وَ إِيَّاكُمْ مِمَّنْ يَسْعَى بِقَلْبِهِ إِلَى مَنَازِلِ الْأَبْرَارِ بِرَحْمَتِهِ.\nتفسير بعض ما في هذه الخطبة من الغريب:\n[قال السيد الشريف رضي الله عنه: قوله (علیه السلام) «يؤر بملاقحه الأر» كناية عن النكاح يقال: أر الرجل المرأة يؤرها إذا نكحها.\nو قوله (علیه السلام) «كأنه قلع داري عنجه نوتيه» «القلع» شراع السفينة و «داري» منسوب إلى دارين و هي بلدة على البحر يجلب منها الطيب و «عنجه» أي عطفه يقال: عنجت الناقة كنصرت أعنجها عنجا إذا عطفتها و «النوتي» الملاح.\nو قوله (علیه السلام) «ضفتي جفونه» أراد جانبي جفونه و الضفتان الجانبان.\nو قوله (علیه السلام) «و فلذ الزبرجد» الفلذ جمع فلذة و هي القطعة.\nو قوله (علیه السلام) «كبائس اللؤلؤ الرطب» الكباسة العذق و «العساليج» الغصون واحدها عسلوج.]\nترجمه:\nراستى چگونه فکرهاى عميق و عقل خداداد مى تواند به (اسرار) اين ويژگى ها راه يابد يا گفتار وصف کنندگان صفت آن را بيان کند و به نظم آورد; حال آن که، کوچک ترين اجزاى آن افکار ژرف انديش را از درک خود ناتوان ساخته و زبان ها را از وصف کردن بازداشته است. منزه است آن کس که عقل ها را در وصف مخلوقى که در چشم ها آشکارش ساخته، ناتوان کرده; به همين جهت آن را (تنها به صورت) موجودى محدود و ترکيبى پر نقش و نگار درک مى کند و زبان ها را از شرح وصف آن عاجز ساخته و از اَداى حق وصفش ناتوان نموده است (با اين حال چگونه مى توان انتظار داشت که عقل و خرد به کنه ذات و صفات آفريدگار اين مخلوق برسد؟).\nپاک و منزه است آن کس که (حتى) براى مورچگان ريز و پشه هاى خرد، دست و پا قرار دارد و بالاتر از آن ها ماهيان بزرگ (و نهنگ ها) و فيل را آفريد و مقرر داشته هر موجودى را که روح در آن دميده سرانجام رهسپار ديار فنا کند (و تنها ذات پاک او باقى و برقرار خواهد بود).\nهرگاه با چشم دل به آن چه از بهشت براى تو وصف مى شود بنگرى، روحت از مواهبى که در اين دنيا پديدار گشته، از شهوات و لذات و زينت ها و زيورهاى خيره کننده اش صرف نظر خواهد کرد و فکرت در ميان درخت هايى که پيوسته شاخه هايش (با جنبش نسيم) به هم مى خورد و ريشه هايش در دل تپه هايى از مشک بر ساحل نهرهاى بهشتى فرو رفته، حيران مى شود، (همچنين) هر گاه به خوشه هايى از لؤلؤ تر، که به شاخه هاى کوچک و بزرگ محکمش آويخته و پيدايش ميوه هاى گوناگون که از درون غلاف هاى خود سر برون کرده، همان ميوه هايى که به آسانى و مطابق دلخواه هر کس چيده مى شود، نگاه کنى واله و حيران خواهى شد (اضافه بر اين) ميزبانان بهشتى از آن ميهمانان در جلو قصرهاى بهشتى با عسل هاى مصفّا و شراب هاى صاف که مستى نمى آورد پذيرايى مى کنند.\nاز کسانى که تقوا و کرامت انسانى خود را تا پايان عمر و هنگام ورود به دارالقرار (سراى جاويدان) حفظ کرده و از ناراحتى هاى نقل و انتقال سفرها (ى مرگ و برزخ) ايمن بوده اند. اى شنونده، اگر قلب خويش را براى رسيدن به آن مناظر زيبا که در آن جاست مشغول دارى، روحت با اشتياق به سوى آن پر مى کشد و از حضور من به همسايگى اهل قبور خواهى شتافت تا هر چه زودتر به آن نعمت ها دست يابى. خداوند ما و شما را به لطف و رحمتش از کسانى قرار دهد که با دل و جان براى رسيدن به منزلگاه هاى نيکان کوشش مى کنند.\nتفسیر:\n♦️فَکَیْفَ تَصِلُ إِلَی صِفَهِ هَذَا عَمَائِقُ الْفِطَنِ، ♦️\nویژگی‌های طاووس را برای شما برشمردیم؛ اکنون چگونه ژرفای اندیشه‌ها می‌تواند به باطن و حقیقت این اوصاف شگفت دست یابد؟!\n♦️أَوْ تَبْلُغُهُ قَرَائِحُ الْعُقُولِ♦️\nیا قریحه‌های عقول چگونه می‌توانند به کنه آفرینش طاووس و سرتاسر موجودات پی ببرند؟!\n♦️أَوْ تَسْتَنْظِمُ وَصْفَهُ أَقْوَالُ الْوَاصِفِینَ! ♦️\nیا گفتار سخن‌سرایان و توصیف‌گران چگونه قادر است آن را در رشته سخن به نظم درآورد؟!\n♦️وَ أَقَلُّ أَجْزَائِهِ قَدْ أَعْجَزَ الْأَوْهَامَ أَنْ تُدْرِکَهُ♦️\nدرحالی‌که کمترین اجزای آن، اندیشه‌ها و اوهام را از درک خویش درمانده و ناتوان ساخته است،\n♦️وَ الْأَلْسِنَهَ أَنْ تَصِفَهُ! ♦️\nو زبان‌ها را از بازگویی و توصیف آن قاصر گردانیده است.\n♦️فَسُبْحَانَ الَّذِی بَهَرَ الْعُقُولَ عَنْ وَصْفِ خَلْقٍ جَلَّاهُ لِلْعُیُونِ، ♦️\nپس پاک و منزه است پروردگاری که خردها را از وصف آفریده‌ای که در برابر دیدگان همگان آشکار ساخته، مبهوت و ناتوان نموده است؛\n♦️فَأَدْرَکَتْهُ مَحْدُوداً مُکَوَّناً، وَ مُؤَلَّفاً مُلَوَّناً، ♦️\nازاین‌رو، خرد آدمی آن را پدیده‌ای محدود، آفریده‌شده، ترکیب‌یافته و رنگارنگ ادراک می‌کند،\n♦️وَ أَعْجَزَ الْأَلْسُنَ عَنْ تَلْخِیصِ صِفَتِهِ، وَ قَعَدَ بِهَا عَنْ تَأْدِیَهِ نَعْتِهِ! ♦️\nو پروردگار زبان‌ها را از خلاصه‌کردن ویژگی‌هایش ناتوان ساخته و از ادای حقِّ توصیفِ آن بازداشته و زمین‌گیر کرده است!\n♦️سُبْحَانَ مَنْ أَدْمَجَ قَوَائِمَ الذَّرَّهِ وَ الْهَمَجَهِ، ♦️\nپاک و منزه است آن که ارکان و پایه‌های اندام مورچه خرد و پشه ریز را چنان محکم و استوار آفرید که در برابر بارهای سنگین تاب می‌آورد؛ همان پشه‌ای که گاه از دیدگان پنهان می‌ماند، در کمال استحکام خلق شده است.\n♦️إِلَی مَا فَوْقَهُمَا مِنْ خَلْقِ الْحِیتَانِ وَ الْفِیَلَهِ، ♦️\nاز ریزترین جنبندگان تا سترگ‌ترین آفریدگان همچون نهنگ‌ها [حِیتَان] و پیلان، مگر می‌توان به کمالْ وصفشان نمود؟!\n«قَالَ رَبُّنَا الَّذِی أَعْطَیٰ کُلَّ شَیْءٍ خَلْقَهُ ثُمَّ هَدَیٰ» (طه/۵۰)\nنهنگ آفریده‌ای است که شیر خود را در آب دریا رها می‌سازد تا نوزادش از آن تغذیه نماید، و نوزاد آمیزه‌ای از آب و شیر را درون می‌کشد و سپس آب را به بیرون می‌راند!\n♦️وَأَی عَلَی نَفْسِهِ أَلَّا یَضْطَرِبَ شَبَحٌ مِمَّا أَوْلَجَ فِیهِ الرُّوحَ، ♦️\nخداوند بر خود لازم شمرده و پیمان بسته است که هیچ کالبد دارای روحی به جنبش و تکاپو درنیاید [یَضْطَرِبَ]،\n♦️إِلَّا وَ جَعَلَ الْحِمَامَ مَوْعِدَهُ، وَ الْفَنَاءَ غَایَتَهُ، ♦️\nمگر آنکه مرگ [حِمَام] را میعادگاه و سرانجام او، و نیستی را غایت واپسین وی قرار داده است.\nاکنون که فنا و زوال به ساحت قدس الهی راه ندارد، چگونه می‌توانید به کنه وصف او راه‌یابید؟!\nامیرالمؤمنین (ع) پس از برشمردن مظاهر جمال الهی و تمثیل شگفت‌انگیز طاووس، به ترسیم زیبایی‌های بی‌کران بهشت می‌پردازند.\n♦️فَلَوْ رَمَیْتَ بِبَصَرِ قَلْبِکَ نَحْوَ مَا یُوصَفُ لَکَ مِنْهَا، ♦️\nای انسان! اگر دیده ظاهربین و بازیگوش را فروگذاری و با چشم دل و خرد بنگری (چنان‌که در روایات آمده مؤمن دارای چهارچشم است؛ دو چشم در سر و دو چشم در باطن دل)، و آنچه را از بهشت برایت وصف می‌شود مشاهده کنی،\n♦️عَزَفَتْ نَفْسُکَ عَنْ بَدَائِعِ مَا أُخْرِجَ إِلَی الدُّنْیَا مِنْ شَهَوَاتِهَا وَ لَذَّاتِهَا وَ زَخَارِفِ مَنَاظِرِهَا، ♦️\nجان تو از تمام شگفتی‌ها، شهوت‌ها، لذت‌های مادی و زیورهای فریبنده این جهان گذران روی برمی‌تابد و هرگز حاضر نمی‌شود آن حقیقت والا را به بهای ناچیز دنیا معامله کند.\n♦️قَوْمٌ لَمْ تَزَلِ الْکَرَامَهُ تَتَمَادَی بِهِمْ حَتَّی حَلُّوا دَارَ الْقَرَارِ، وَ أَمِنُوا نُقْلَهَ الْأَسْفَارِ. ♦️\nاهل بهشت خاندانی هستند که کرامت همواره همراه و همنشین آنان بوده است تا آنکه در سرای آرامش و جاودان [دَارَ الْقَرَارِ] فرود آمدند و از سختیِ کوچ‌ها و دگرگونی سفرها [نُقْلَهَ الْأَسْفَارِ] ایمنی یافتند.\n«وَ لَقَدْ کَرَّمْنَا بَنِی آدَمَ» (اسراء/۷۰)؛\nخداوند به فرزندان آدم کرامت ذاتی عطا فرموده است؛ بنابراین انسان در پی کسب اولیه کرامت نیست، بلکه رسالت او نگاهبانی و صیانت از این ودیعه الهی است. ازاین‌رو، هتک حرمت و اهانت به خود یا دیگران روا نیست، چراکه گوهر کرامت آدمی را خدشه‌دار می‌سازد؛ همچنین نباید فروتنی را با خواری و تضعیف عزت‌نفس اشتباه گرفت.\nسفر مرگ پایان راه نیست، بلکه ورود به عرصه پرفرازونشیب برزخ است. ازاین‌رو برخی در گذر از این منازل آرام و ایمن‌اند و برخی مضطرب و هراسان؛ آن که گوهر کرامت را پاس داشته باشد در آرامش است و بهشتیان آنان‌اند که لوای کرامت را تا دامنه قیامت برافراشته نگاه داشتند.\nدر کتاب‌های تفسیر البرهان و مرآة العقول نقل شده است که حضرت عیسی (ع) دعا فرمود تا خداوند پسرخاله‌اش، حضرت یحیی بن زکریا (ع)، را زنده گرداند. پروردگار دعایش را مستجاب ساخت و یحیی از خاک برآمد و فرمود: برای چه مرا فراخواندی؟ حضرت عیسی (ع) فرمود: مشتاق همنشینی و انس با تو بودم. یحیی (ع) عرضه داشت: هنوز حرارت و سوزش مرگ از کالبدم رخت بر نبسته است؛ آیا می‌خواهی دوباره مرا به این سختی بازگردانی؟! آنگاه به درون آرامگاه خویش بازگشت.\n♦️فَلَوْ شَغَلْتَ قَلْبَکَ أَیُّهَا الْمُسْتَمِعُ بِالْوُصُولِ إِلَی مَا یَهْجُمُ عَلَیْکَ مِنْ تِلْکَ الْمَنَاظِرِ الْمُونِقَهِ، لَزَهِقَتْ نَفْسُکَ شَوْقاً إِلَیْهَا، ♦️\nای شنونده سخن من! با دیدگان ظاهری کاری ندارم؛ اگر دل خویش را به ادراک این مناظر دل‌انگیز و شگفت‌آور پیوند زنی، به‌یقین جانت از شدت اشتیاق به آن سرای جاوید از قالب تن پرواز خواهد کرد و کسی تاب ماندن در کالبد خاکی را نخواهد داشت.\nحضرت در خطبه همام (متقین) نیز در توصیف پرهیزگاران فرمودند: اگر اجل مقدر الهی نبود، جان‌هایشان حتی یک‌چشم برهم‌زدن از شوق پاداش در کالبد تن قرار نمی‌گرفت.\n♦️وَ لَتَحَمَّلْتَ مِنْ مَجْلِسِی هَذَا إِلَی مُجَاوَرَهِ أَهْلِ الْقُبُورِ اسْتِعْجَالًا بِهَا. ♦️\nو بی‌درنگ از همین مجلس روی برمی‌تافتی و به‌شتاب و اشتیاق نیل به بهشت، همسایگی اهل قبور را برمی‌گزیدی.\nدر نگاه ژرف حضرت، آرامگاه آدمی مدخل و دروازه گشایش به‌سوی فردوس برین است. کسی که کلام امام را با عمق جان نوشیده باشد، پیوسته در آرزوی پرواز است و نگاه او با نگاه کسی که گور را سراسر وحشت و عذاب می‌پندارد تفاوت بنیادین دارد. اگر کسی خواهان آن است که مسیر حیات را یکسره به‌سوی رضوان الهی بپیماید، شایسته است در حلقه تعالیم امیرالمؤمنین (ع) زانوی ادب بزند. تعبیر حضرت در بیانی دیگر چنین است: «از من فرمان برید تا شما را به فضل الهی به بهشت رسانم».\n♦️جَعَلَنَا اللَّهُ وَ إِیَّاکُمْ مِمَّنْ یَسْعَی بِقَلْبِهِ إِلَی مَنَازِلِ الْأَبْرَارِ بِرَحْمَتِهِ. ♦️\nخداوند ما و شما را به فضل و رحمت بی‌کران خویش از زمره کسانی قرار دهد که با تمام پهنای دل در راه دستیابی به جایگاه نیکان و پاکان گام برمی‌دارند.\nمراتب بهشت درجاتی گوناگون دارد و اعمال امروز ما سازنده درجات فردای ماست؛ در قرآن مجید گاه تعبیر «لَهُمْ دَرَجَاتٌ» آمده که حاکی از استقرار بهشتیان در مراتب عالی است، و گاه تعبیر «هُمْ دَرَجَاتٌ» ذکر شده که نشان می‌دهد مؤمن خود عین درجه و میزانِ هدایت دیگران گردیده است.\n♦️وَ لَذَهِلَتْ بِالْفِکْرِ فِی اصْطِفَاقِ أَشْجَارٍ غُیِّبَتْ عُرُوقُهَا فِی کُثْبَانِ الْمِسْکِ♦️\nو اندیشه تو سخت مبهوت و سرگشته می‌گشت [ذَهِلَتْ] از نغمه برخورد شاخسار درختان بهشتی [اصْطِفَاقِ]؛ درختانی که ریشه‌هایشان در تپه‌هایی از مشک ناب پنهان شده است،\n♦️عَلَی سَوَاحِلِ أَنْهَارِهَا، ♦️\nدر کرانه‌های نهرهای خروشان و زلال بهشتی.\nاگر نغمه دل‌انگیز شاخ‌وبرگ درختان بهشت را به هنگام وزش نسیم برای شما بازگو کنم، چنان سرمست می‌شوید که دیگر هرگز به جلوه‌های خاکی دنیا نخواهید نگریست و اندیشه غرق در حیرت می‌گردد. ریشه‌های کهن‌سال این درختان تنومند در بستری از مشک خوش‌بو نهفته است و تماشای این صحنه بی‌بدیل در ساحل جویبارهای بهشت، آدمی را ازخودبی‌خود می‌سازد.\n♦️وَ فِی تَعْلِیقِ کَبَائِسِ اللُّؤْلُؤِ الرَّطْبِ فِی عَسَالِیجِهَا وَ أَفْنَانِهَا، ♦️\nو همچنین مبهوت می‌شدی از آویختگی خوشه‌های مروارید تروتازه [اللُّؤْلُؤِ الرَّطْبِ] بر شاخه‌های نرم، ظریف و گسترده آن درختان [عَسَالِیجِهَا وَ أَفْنَانِهَا].\nاگر برایتان از خوشه‌های پرشکوه لؤلؤ وصف نمایم که چگونه بر ساقه‌های نازک و لطیف تکیه زده‌اند و آن شاخه‌های باریک با چه استواری به بدنه اصلی پیوند خورده‌اند، عقل واله و شیدا گشته و انسان از تمام جلوه‌های صوری و فریبنده خاک دل برمی‌کند.\n♦️طُلُوعِ تِلْکَ الثِّمَارِ مُخْتَلِفَهً فِی غُلُفِ أَکْمَامِهَا، ♦️\nو نمایان گشتن آن میوه‌های گوناگون از درون غلاف‌ها و شکوفه‌های پوشاننده [غُلُفِ أَکْمَامِهَا] که در نگاه باطن رخ می‌نمایند،\n♦️تُجْنَی مِنْ غَیْرِ تَکَلُّفٍ فَتَأْتِی عَلَی مُنْیَهِ مُجْتَنِیهَا. ♦️\nمیوه‌هایی که بدون کوچک‌ترین زحمت و رنجی چیده می‌شوند و درست مطابق با میل و آرزوی چیننده فرود می‌آیند.\nبرای این فراز دو معنا متصور است: نخست آنکه شاخه میوه خود به‌سوی فرد بهشتی متمایل می‌شود، و دوم آنکه هر میوه‌ای را نیت کند بلافاصله به همان صورت درمی‌آید. اگر میوه‌های پرشکوه فردوس را وصف کنم که از حیث طعم، رنگ و جنس در غایت تنوع‌اند و در پوششی از گلبرگ‌ها جای گرفته‌اند، درمی‌یابید که برای تناول آن‌ها نیازی به انتظار برای دگرگونی فصل‌ها یا رنج چیدن نیست، بلکه به‌محض اراده در دستان شما قرار می‌گیرند.\n«فِی جَنَّةٍ عَالِیَةٍ * قُطُوفُهَا دَانِیَةٌ» (حاقه/۲۲-۲۳)؛\nبهشتیان در باغ‌های بلندمرتبه‌ای جای دارند که میوه‌هایش بس در دسترس و نزدیک است؛\n«فَتَأْتِی عَلَیٰ مُنْیَةِ مُجْتَنِیهَا»؛ بر مبنای اشتیاق و نیت چیننده، میوه فرامی‌رسد؛ چراکه سرای واپسین، دارِ تحقق اراده است نه سرای رنج و تعب؛ ازاین‌رو بااراده انسان دگرگون می‌شود. بدین سبب هنگامی که از حضرت امام رضا (ع) پیرامون میوه‌ای که حضرت آدم از آن تناول کرد پرسیدند که آیا گندم بود یا سیب یا عنبی دیگر، فرمودند: در بهشت، نعمت‌ها بر وفق اراده و میل مؤمن تغییر می‌یابند.\nامیر بیان، حقایق فرازمینی را در این کلمات شیوا تبیین فرموده و سپس به جنبه‌ای دیگر از مواهب بهشت اشاره می‌فرمایند:\n♦️یُطَافُ عَلَی نُزَّالِهَا فِی أَفْنِیَهِ قُصُورِهَا بِالْأَعْسَالِ الْمُصَفَّقَهِ، وَ الْخُمُورِ الْمُرَوَّقَهِ، ♦️\nخدمتگزاران بهشتی در گرداگرد سرای و حیاط کاخ‌ها، بر فرود آمدگان و ساکنان بهشت با ظرف‌هایی لبریز از عسل‌های تصفیه‌شده، زلال و پالوده، و باده‌های پاکیزه و گوارا [الْخُمُورِ الْمُرَوَّقَهِ] گردش می‌کنند.\nاین گردش و پذیرایی یا به هیئت جویبارهای روان از عسل پاکیزه جریان دارد یا با طواف خادمان و حوریانی است که گرداگرد ساکنان فردوس حلقه می‌زنند. در زیارت عاشورا نیز عبارت «حَلَّتْ بِفِنَائِکَ» به‌کاررفته که ناظر بر یاران پاک‌باخته‌ای است که در حریم و گرداگرد حضرت سیدالشهدا (ع) فرود آمدند.\nشبهه: چگونه نوشیدنی‌ای که در حیات مادی تحریم گردیده، در سرای دیگر پاداش مؤمنان قرار گرفته است؟\nپاسخ: باده بهشتی از سنخ نوشیدنی‌های مست‌کننده و زایل‌کننده عقل دنیوی نیست؛ چنان‌که در سوره مبارکه واقعه می‌فرماید:\n«وَ کَأْسٍ مِنْ مَعِینٍ * لَا یُصَدَّعُونَ عَنْهَا وَ لَا یُنْزِفُونَ» (واقعه/۱۸-۱۹)؛\nشراب طهور بهشتی نه سردردی می‌آورد و نه گوهر عقل را تباه می‌سازد؛ حال‌آنکه مسکرات دنیا زایل‌کننده تن و روان‌اند. میان شراب دنیا و باده فردوس تباین و تمایز بنیادین برقرار است و هیچ‌گونه سنخیت و شباهتی میان آن‌ها وجود ندارد.\nدو روایت ارزشمند به نقل از فقیه برجسته، آیت‌الله خویی (رحمت‌الله علیه)، در کتاب منهاج البراعة ثبت شده است:\n۱. در بحبوحه نبرد جمل، عرق بر چهره مبارک امیرالمؤمنین (ع) نشسته بود؛ حضرت آبی طلب فرمودند. شخصی عرضه داشت: با توجه به‌شدت خستگی، شربتی از عسل گواراتر است. چون قطره‌ای از آن به کام مبارک رسید، فرمودند: این عسل از نوع عسل طائف است! آن مرد شگفت‌زده گفت: یا امیرالمؤمنین! در این معرکه سهمگین که از بیم و هراس جان‌ها به لب رسیده، چگونه نوع عسل را تشخیص دادید؟! حضرت فرمودند: برادرم! بدان و آگاه باش، به خدا سوگند سینه علی هرگز از اضطراب لبریز نمی‌شود؛ چنان سعه‌صدر و طمأنینه‌ای دارم که اگر هزاران واقعه سهمگین‌تر از این نیز رخ دهد، آرامش مرا بر هم نخواهد زد.\n۲. رسول گرامی اسلام (ص) فرمودند: در شب معراج، در آسمان ششم به درختی پرشکوه و بی‌مانند رسیدم که هرگز نظیر آن را ندیده بودم. از جبرئیل هویت آن را جویا شدم؛ گفت: این درخت طوباست. در این هنگام نغمه‌ای بم و صدایی پرطنین از آن درخت به گوش رسید؛ پرسیدم این چه آوایی است؟ جبرئیل عرضه داشت: این درخت سخن می‌گوید و ندا می‌دهد: ای علی! چقدر مشتاق دیدار تو هستم!\n«الْحَمْدُ لِلَّهِ الَّذِی جَعَلَنَا مِنَ الْمُتَمَسِّکِینَ بِوِلَایَةِ أَمِیرِالْمُؤْمِنِینَ عَلِیِّ بْنِ أَبِی طَالِبٍ وَ الْأَئِمَّةِ الْمَعْصُومِینَ عَلَیْهِمُ السَّلَامُ»"]});
